    relations = []

    # Cause-Effect relation
    if "caused" in response or "led to" in response or "resulted in" in response or "because" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} caused" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Cause-Effect",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Evidence relation
    if "shows" in response or "indicates" in response or "confirms" in response or "as shown by" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} shows" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Evidence",
                        "coupling": "entailment",
                        "strength_band": "strong"
                    })

    # Restatement relation
    if "that is" in response or "in other words" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} that is" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Restatement",
                        "coupling": "equivalence",
                        "strength_band": "strong"
                    })

    # Refutation relation
    if "cannot be squared with" in response or "rules out" in response or "it cannot have, since" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} cannot be squared with" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Refutation",
                        "coupling": "contradiction",
                        "strength_band": "strong"
                    })

    # Contrast relation
    if "by contrast" in response or "whereas" in response or "but" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} by contrast" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
