            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} although" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Concession",
                        "coupling": "none",
                        "strength_band": "moderate"
                    })

    # Alternative relation
    if "either" in response or "or" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} either" in response and f"{atoms[str(j)]}" in response:
                    relations.append({
                        "source": i,
                        "target": j,
                        "sense": "Alternative",
                        "coupling": "exclusive",
                        "strength_band": "strong"
                    })

    # Disjunction relation
    if "at least one of" in response:
        for i in range(1, len(atoms) + 1):
            for j in range(i + 1, len(atoms) + 1):
                if f"{atoms[str(i)]} at least one of" in response and f"{atoms[str(j)]}" in response:
